    c.bench_function("Std Eq Comps", |b| {
        b.iter(|| {
            // Use black_box to prevent compiler optimizations from 
            // skipping the code you want to measure
            black_box(eq_comps(black_box(path.as_ref()), black_box(path.as_ref())))
