#[simd_test(enable = "sve,f64mm")]
unsafe fn test_svld1ro_s16() {
    if svcntb() < 32 {
        println!("Skipping test_svld1ro_s16 due to SVE vector length");
        return;
    }
    svsetffr();
    let loaded = svld1ro_s16(svptrue_b16(), I16_DATA.as_ptr());
    assert_vector_matches_i16(
        loaded,
        svtrn1q_s16(
            svdupq_n_s16(
                0usize as i16,
                1usize as i16,
                2usize as i16,
                3usize as i16,
                4usize as i16,
                5usize as i16,
                6usize as i16,
                7usize as i16,
            ),
            svdupq_n_s16(
                8usize as i16,
                9usize as i16,
                10usize as i16,
                11usize as i16,
                12usize as i16,
                13usize as i16,
                14usize as i16,
                15usize as i16,
            ),
        ),
    );
}
